import { useState, useEffect, useCallback, lazy, Suspense } from 'react'

// Atomic Components
import MainLayout from './components/templates/MainLayout'
import AppHeader from './components/organisms/AppHeader'
import LoadingOverlay from './components/molecules/LoadingOverlay'
import ContentPanel from './components/organisms/ContentPanel'
const CodePreviewPanel = lazy(() => import('./components/CodePreviewPanel'))

// Hooks
import { usePyodide } from './hooks/usePyodide'
import { useChapters } from './hooks/useChapters'
import { usePythonRunner } from './hooks/usePythonRunner'
import useBodyContent from './hooks/useBodyContent'

// Utils
import { MODULE_MAPPING, MODULE_DEPS } from './config'
import { loadChapterDatasets } from './utils/pyodide-loader'
import { PANDAS_DATAREADER_SHIM } from './utils/python-shims'
import { initMatplotlib } from './utils/matplotlib-handler.js'

import './App.css'

function App() {
  // 1. Atomic States via Hooks
  const { pyodide, loading: pyLoading, progress, message, error: pyError } = usePyodide()
  const {
    chapters, setChapters, chaptersLoading,
    currentChapter, setCurrentChapter, loadChapterData
  } = useChapters()

  const {
    output, setOutput, plotImages, isRunning, runCode
  } = usePythonRunner(pyodide)

  // 2. Local App States
  const [currentScript, setCurrentScript] = useState(null)
  const [selectedTopicId, setSelectedTopicId] = useState('')
  const [isSidebarOpen, setIsSidebarOpen] = useState(true)
  const [installedPackages] = useState(new Set())
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('theme')
    return saved ? saved === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches
  })

  // Chapter content helper
  const { bodyContent } = useBodyContent(currentChapter)

  // 3. Effects & Logic
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', darkMode ? 'dark' : 'light')
    localStorage.setItem('theme', darkMode ? 'dark' : 'light')
  }, [darkMode])

  // Initial chapter index load
  useEffect(() => {
    fetch(`${import.meta.env.BASE_URL}data/chapters_index.json?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => {
        setChapters(data.chapters || [])
        setChaptersLoading(false) // Trigger instant entry
      })
      .catch(err => {
        console.error('Failed to load chapter index:', err)
        setChaptersLoading(false)
      })
  }, [setChapters, setChaptersLoading])

  const handleChapterSelect = useCallback(async (chapter) => {
    setCurrentScript(null)
    setOutput('')

    const fullData = await loadChapterData(chapter.id)
    if (fullData) {
      setCurrentChapter(fullData)
      // Load datasets if any
      if (pyodide && (fullData.datasets || fullData.content?.datasets)) {
        loadChapterDatasets(pyodide, fullData.datasets || fullData.content.datasets)
      }
    }
  }, [loadChapterData, pyodide, setCurrentChapter, setOutput]);

  const handleCodeClick = useCallback((script) => {
    setCurrentScript(script)
  }, []);

  const handleRun = useCallback(async (code, neededModules = []) => {
    if (!pyodide) return

    // Dynamic Dependency Loading (Atomized)
    const toLoad = neededModules.filter(m => !installedPackages.has(m))
    if (toLoad.length > 0) {
      setOutput(prev => prev + `📦 正在載入套件 [${toLoad.join(', ')}]...\n`)
      for (const mod of toLoad) {
        try {
          const pkg = MODULE_MAPPING[mod] || mod
          if (pkg.endsWith('.whl')) {
            const micropip = pyodide.pyimport('micropip')
            await micropip.install(`${import.meta.env.BASE_URL}${pkg}`)
          } else {
            await pyodide.loadPackage(pkg)
          }

          if (mod === 'pandas_datareader') await pyodide.runPythonAsync(PANDAS_DATAREADER_SHIM)
          if (mod === 'matplotlib') await initMatplotlib(pyodide)

          installedPackages.add(mod)
        } catch (e) {
          console.warn(`Package ${mod} load failed:`, e)
        }
      }
    }

    runCode(code)
  }, [pyodide, installedPackages, runCode, setOutput]);

  // 4. Render Layout (Atomic Design)
  return (
    <div className="app-root">
      {/*
          秒速啟動優化：
          Splash 遮罩僅在「目錄索引」載入時顯示 (通常 < 0.5s)。
          一旦目錄載入完成，使用者立即進入主介面，
          Python 引擎初始化轉入背景執行 (顯示於頂部 StatusBadge)。
      */}
      {chaptersLoading && (
        <LoadingOverlay
          progress={progress}
          message={message}
          stage="loading"
        />
      )}

      <MainLayout
        isSidebarOpen={isSidebarOpen}
        header={
          <AppHeader
            chapters={chapters}
            currentChapter={currentChapter}
            bodyContent={bodyContent}
            onChapterSelect={handleChapterSelect}
            onScriptSelect={setCurrentScript}
            currentScript={currentScript}
            selectedTopicId={selectedTopicId}
            onTopicSelect={setSelectedTopicId}
            pyStatus={{
              status: pyLoading ? 'loading' : (pyError ? 'error' : 'ready'),
              message: pyLoading ? '正在初始化...' : (pyError ? '初始化失敗' : 'Python 引擎就緒')
            }}
            darkMode={darkMode}
            setDarkMode={setDarkMode}
          />
        }
        content={
          <ContentPanel
            chapter={currentChapter}
            bodyContent={bodyContent}
            onCodeClick={handleCodeClick}
            selectedTopicId={selectedTopicId}
            output={output}
            isRunning={isRunning}
            plotImages={plotImages}
          />
        }
        footer={
          <div className="app-footer-info">
            &copy; 2026 FRM Book 2 Python Scientific Risk Management Lab. Powered by Pyodide & WebAssembly.
          </div>
        }
      />

      {/* Lazy Panels */}
      <Suspense fallback={null}>
        {currentScript && (
          <CodePreviewPanel
            script={currentScript}
            onRun={(code) => handleRun(code, currentScript.modules || [])}
            onClose={() => setCurrentScript(null)}
          />
        )}
      </Suspense>
    </div>
  )
}

export default App

import { useRegisterSW } from 'virtual:pwa-register/react'
import 'react'
import './ReloadPrompt.css'

function ReloadPrompt() {
    const {
        offlineReady: [offlineReady, setOfflineReady],
        needRefresh: [needRefresh, setNeedRefresh],
        updateServiceWorker,
    } = useRegisterSW({
        onRegisteredSW(swUrl, r) {
            console.debug(`Service Worker at: ${swUrl}`)
            if (r) {
                setInterval(() => {
                    r.update()
                }, 60 * 60 * 1000) // Check for updates every hour
            }
        },
        onRegisterError(error) {
            console.warn('SW registration error', error)
        },
    })

    const close = () => {
        setOfflineReady(false)
        setNeedRefresh(false)
    }

    // Auto-update if configured (optional, but safer to prompt user)
    // useEffect(() => {
    //   if (needRefresh) {
    //     console.log('New content available, auto-updating...')
    //     updateServiceWorker(true)
    //   }
    // }, [needRefresh])

    return (
        <div className="ReloadPrompt-container">
            {(offlineReady || needRefresh) && (
                <div className="ReloadPrompt-toast">
                    <div className="ReloadPrompt-message">
                        {offlineReady
                            ? 'App ready to work offline'
                            : 'New content available, click on reload button to update.'}
                    </div>
                    {needRefresh && (
                        <button className="ReloadPrompt-toast-button" onClick={() => updateServiceWorker(true)}>
                            Reload
                        </button>
                    )}
                    <button className="ReloadPrompt-toast-button" onClick={close}>
                        Close
                    </button>
                </div>
            )}
        </div>
    )
}

export default ReloadPrompt

import { useState, useCallback, useMemo } from 'react';

/**
 * Hook to manage chapter loading and caching
 */
export function useChapters() {
    const [chapters, setChapters] = useState([]);
    const [chaptersLoading, setChaptersLoading] = useState(true);
    const [currentChapter, setCurrentChapter] = useState(null);
    const [chapterCache, setChapterCache] = useState({});

    const loadChapterData = useCallback(async (chapterId) => {
        if (chapterCache[chapterId]) {
            return chapterCache[chapterId];
        }

        try {
            setChaptersLoading(true);
            const response = await fetch(`${import.meta.env.BASE_URL}data/chapters_${chapterId}.json?t=${Date.now()}`);
            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

            const rawText = await response.text();
            let fullData = null;

            try {
                fullData = JSON.parse(rawText);
            } catch {
                // Fallback: recover from bad escapes
                try {
                    const sanitized = rawText.replace(/\\(?!["\\/bfnrtu])/g, "\\\\");
                    fullData = JSON.parse(sanitized);
                } catch (e) {
                    throw new Error(`Failed to parse chapter data: ${e.message}`);
                }
            }

            setChapterCache(prev => ({ ...prev, [chapterId]: fullData }));
            setChaptersLoading(false);
            return fullData;
        } catch (error) {
            console.error(`Failed to load chapter ${chapterId}:`, error);
            setChaptersLoading(false);
            return null;
        }
    }, [chapterCache]);

    return {
        chapters,
        setChapters,
        chaptersLoading,
        setChaptersLoading,
        currentChapter,
        setCurrentChapter,
        loadChapterData
    };
}

// pyodide-loader.js (Book2)
import { BASE_ENV_SETUP, PYMOO_SHIM, PANDAS_DATAREADER_SHIM, SCIPY_RVS_SHIM, DATASET_SHIM, MCINT_SHIM, SCIPY_STUB, ARCH_STUB, MIBIAN_STUB, QPSOLVERS_SHIM } from './python-shims';

let pyodideInstance = null;
let initializationPromise = null;

class SmoothProgress {
    constructor(onProgress) {
        this.onProgress = onProgress;
        this.current = 0;
        this.message = '';
    }

    start() {
        this.onProgress(0, '準備啟動...');
    }

    update(target, message) {
        this.current = target;
        if (message) this.message = message;
        this.onProgress(this.current, this.message);
    }

    async yieldToUI() {
        return new Promise(resolve => setTimeout(resolve, 0));
    }

    finish(message = 'Ready!') {
        this.current = 100;
        this.onProgress(100, message);
    }
}

async function ensurePyodideScript() {
    if (window.loadPyodide) return;
    return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = 'https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.js';
        script.onload = () => resolve();
        script.onerror = () => reject(new Error('Failed to load Pyodide script'));
        document.head.appendChild(script);
    });
}

