/**
 * Lazy load datasets for a specific chapter
 */
export async function loadChapterDatasets(pyodide, chapterId) {
    if (!pyodide || !chapterId) return;
    const normalizedId = chapterId.toLowerCase();
    const files = DATASET_REGISTRY[normalizedId];
    if (!files || files.length === 0) return;

    for (const file of files) {
        const { filename, displayPath } = file;
        const virtualPath = `/data/${displayPath}`;
        try {
            if (pyodide.FS.analyzePath(virtualPath).exists) continue;
        } catch { /* proceed */ }

        try {
            const fetchUrl = `${import.meta.env.BASE_URL}data/datasets/${normalizedId}/${filename}`;
            const response = await fetch(fetchUrl);
            if (!response.ok) continue;

            // Guard: reject HTML responses masquerading as data files (SPA fallback)
            const ct = (response.headers.get('content-type') || '').toLowerCase();
            if (ct.includes('text/html')) continue;

            const arrayBuffer = await response.arrayBuffer();
            const data = new Uint8Array(arrayBuffer);
            const dir = virtualPath.substring(0, virtualPath.lastIndexOf('/'));
            const dirs = dir.split('/').filter(p => p);
            let currentPath = '';
            for (const d of dirs) {
                currentPath += '/' + d;
                try { pyodide.FS.mkdir(currentPath); } catch { /* ignore */ }
            }
            pyodide.FS.writeFile(virtualPath, data);
        } catch (err) {
            console.error(`[Dataset] Failed to load ${filename}:`, err);
        }
    }
}

/**
 * Initialize Light-weight Pyodide (Core Only)
 */
export async function loadPyodide(onProgress) {
    if (pyodideInstance) {
        if (onProgress) onProgress(100, 'Ready');
        return pyodideInstance;
    }
    if (initializationPromise) return initializationPromise;

    initializationPromise = (async () => {
        const smoother = new SmoothProgress(onProgress);
        smoother.start();

        try {
            smoother.update(15, '正在啟動 Python 直譯器 (v0.26.4)...');
            await ensurePyodideScript();

            let pyodide = null;
            let retries = 3;
            while (retries > 0) {
                try {
                    const indexURL = 'https://cdn.jsdelivr.net/pyodide/v0.26.4/full/';
                    pyodide = await window.loadPyodide({ indexURL });
                    break;
                } catch (e) {
                    console.warn(`Failed to load Pyodide (attempts left: ${retries - 1}):`, e);
                    retries--;
                    if (retries === 0) throw e;
                    await new Promise(resolve => setTimeout(resolve, 300));
                }
            }

            smoother.update(60, '正在掛載虛擬檔案系統...')
            try {
                pyodide.FS.mkdir('/mnt');
                pyodide.FS.mount(pyodide.FS.filesystems.IDBFS, {}, '/mnt');
                pyodide.FS.syncfs(true, (err) => {
                    if (err) console.warn('IDBFS sync failed:', err);
                });
            } catch (e) {
                console.warn('IDBFS mount skipped:', e);
            }

            smoother.update(80, '正在配置 Python 基礎運行環境...')
            await pyodide.runPythonAsync(`
import sys
import os
import builtins
import js

if not os.path.exists('/data'):
    os.makedirs('/data')
sys.path.append('/data')

def custom_input(prompt = ""):
    try:
        val = js.window.prompt(prompt if prompt else "")
        return val if val is not None else ""
    except Exception: return ""
builtins.input = custom_input
            `);

            pyodideInstance = pyodide;
            initializationPromise = null;

            // Finish splash early!
            smoother.finish('引擎初始化完成！ (模組將在背景持續載入)');
            return pyodide;
        } catch (error) {
            initializationPromise = null;
            if (smoother.interval) clearInterval(smoother.interval);
            console.error('Failed to load Pyodide:', error);
            throw error;
        }
    })();

    return initializationPromise;
}

// Track heavy loading state
let isHeavyLoaded = false;
let heavyLoadingPromise = null;

/**
 * Background load heavy packages (SciPy, Scikit-learn, etc.)
 */
export async function preloadHeavyPackages(pyodide) {
    if (isHeavyLoaded || heavyLoadingPromise) return heavyLoadingPromise;

    heavyLoadingPromise = (async () => {
        try {
            console.warn('[Background] Starting heavy initialization...');

            // 1. Core compiled packages (Parallel Load)
            const heavyCore = ['numpy', 'pandas', 'matplotlib', 'scipy', 'statsmodels', 'scikit-learn'];
            await Promise.all(heavyCore.map(async (pkg) => {
                try {
                    await pyodide.loadPackage(pkg);
                } catch (e) {
                    console.warn(`[Background] loadPackage failed for ${pkg}:`, e);
                }
            }));

            // 2. Core initialization (Need Numpy/Pandas)
            const runShim = async (code, label) => {
                try { await pyodide.runPythonAsync(code); } catch (e) { console.warn(`[Background] Shim failed: ${label}`); }
            };

            await runShim(BASE_ENV_SETUP, 'BASE_ENV_SETUP');
            await runShim(DATASET_SHIM, 'DATASET_SHIM');

            // 2. Init Micropip (Moved here from main boot)
            await pyodide.loadPackage('micropip');
            const micropip = pyodide.pyimport('micropip');
            const baseURL = import.meta.env.BASE_URL || '/';

            const localWheels = [
                'pandas_datareader-0.10.0-py3-none-any.whl',
                'openpyxl-3.1.5-py2.py3-none-any.whl',
                'seaborn-0.13.2-py3-none-any.whl',
                'numpy_financial-1.0.0-py3-none-any.whl',
                'pymoo-0.4.1-py3-none-any.whl',
                'pyodide_http-0.2.2-py3-none-any.whl',
                'requests-2.32.5-py3-none-any.whl'
            ];

            const remotePackages = ['chart_studio', 'plotly', 'prettytable', 'tabulate', 'qpsolvers'];

            // Sequential wheel install for stability within background worker
            for (const wh of localWheels) {
                try { await micropip.install(`${baseURL}wheels/${wh}`); } catch (e) { console.warn(`[Background] Failed wheel ${wh}`, e); }
            }
            for (const pkg of remotePackages) {
                try { await micropip.install(pkg); } catch (e) { console.warn(`[Background] Failed package ${pkg}`, e); }
            }

            // 4. Stubs & Secondary Shims
            await runShim(SCIPY_STUB, 'SCIPY_STUB');
            await runShim(ARCH_STUB, 'ARCH_STUB');
            await runShim(MIBIAN_STUB, 'MIBIAN_STUB');
            await runShim(MCINT_SHIM, 'MCINT_SHIM');
            await runShim(QPSOLVERS_SHIM, 'QPSOLVERS_SHIM');
            await runShim(SCIPY_RVS_SHIM, 'SCIPY_RVS_SHIM');
            await runShim(PYMOO_SHIM, 'PYMOO_SHIM');
            await runShim(PANDAS_DATAREADER_SHIM, 'PANDAS_DATAREADER_SHIM');

            isHeavyLoaded = true;
            console.warn('[Background] All heavy packages and shims ready.');
        } catch (e) {
            console.error("⚠️ [Background] Heavy package preload failed:", e);
            heavyLoadingPromise = null;
        }
    })();

    return heavyLoadingPromise;
}

export function getPyodide() {
    return pyodideInstance;
}

export async function runPythonWithTimeout(pyodide, code, timeout = 30000) {
    let timeoutId;
    const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => {
            reject(new Error(`Execution timed out after ${timeout / 1000} seconds`));
        }, timeout);
    });

    try {
        const result = await Promise.race([
            pyodide.runPythonAsync(code),
            timeoutPromise
        ]);
        return result;
    } finally {
        clearTimeout(timeoutId);
    }
}

export async function cleanupPyodide(pyodide) {
    if (!pyodide) return;
    try {
        await pyodide.runPythonAsync(`
import gc
import matplotlib.pyplot as plt
plt.close('all')
gc.collect()
        `);
    } catch { /* ignore */ }
}
